import{_ as a,o as t,c as s,a4 as i}from"./chunks/framework.ClGzHnIj.js";const m=JSON.parse('{"title":"Machine partagée","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://lognebudo.github.io/llmxray/docs/fr/guide/shared-box.html"}]]},"headers":[],"relativePath":"fr/guide/shared-box.md","filePath":"fr/guide/shared-box.md","lastUpdated":1792397420000}'),o={name:"fr/guide/shared-box.md"};function l(u,e,r,n,d,c){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="machine-partagee" tabindex="-1">Machine partagée <a class="header-anchor" href="#machine-partagee" aria-label="Permalink to &quot;Machine partagée&quot;">​</a></h1><p>La page <strong>Machine partagée</strong> répond à une question : pourquoi Ollama est-il lent en ce moment, et lequel de mes outils en est la cause. Elle liste ce que chaque outil a demandé au démon et ce que cela a coûté aux autres outils, en secondes, avec le réglage à changer.</p><p><strong>Élément de la barre latérale :</strong> Machine partagée (sous Radiographie de l&#39;invite) <strong>Route :</strong> <code>/shared-box</code><strong>Ajouté dans :</strong> v0.8.0 (octobre 2026) <strong>Nécessite :</strong> des tours de plus d&#39;un outil sur la page En direct. Avec un seul outil, il n&#39;y a personne à qui coûter quoi que ce soit.</p><h2 id="a-quoi-ca-sert" tabindex="-1">À quoi ça sert ? <a class="header-anchor" href="#a-quoi-ca-sert" aria-label="Permalink to &quot;À quoi ça sert ?&quot;">​</a></h2><p>Ollama sert tout ce qui arrive et ne dit jamais qui l&#39;a ralenti. Trois réglages voyagent dans les requêtes et changent l&#39;état du démon pour tout le monde :</p><ul><li><code>keep_alive</code>. Un outil qui envoie <code>keep_alive: 0</code> décharge le modèle après chacune de ses requêtes. L&#39;outil suivant paie le rechargement, souvent plusieurs dizaines de secondes.</li><li><code>num_ctx</code>. Le démon réserve toute la fenêtre de contexte d&#39;avance. Un outil qui demande un contexte de 128 000 tokens pour des invites de 4 000 tokens prend plusieurs gigaoctets pour lui seul, et le démon passe de plusieurs requêtes à la fois à une seule.</li><li>Les changements de modèle. Un outil qui charge un autre modèle décharge celui que les autres utilisaient.</li></ul><p>Ollama ne rapporte rien de tout cela. Le port d&#39;observation voit chaque requête, il peut donc tenir le registre.</p><h2 id="la-phrase-du-haut" tabindex="-1">La phrase du haut <a class="header-anchor" href="#la-phrase-du-haut" aria-label="Permalink to &quot;La phrase du haut&quot;">​</a></h2><p>En haut : combien d&#39;outils, combien de modèles, sur quelle durée, et ce que leurs réglages ont coûté aux autres. Si la réponse est rien, la page le dit.</p><h2 id="qui-a-coute-quoi-a-qui" tabindex="-1">Qui a coûté quoi à qui <a class="header-anchor" href="#qui-a-coute-quoi-a-qui" aria-label="Permalink to &quot;Qui a coûté quoi à qui&quot;">​</a></h2><p>Une ligne par outil, triée par le temps pris aux autres. Chaque ligne dit en mots simples ce que l&#39;outil a demandé et ce que cela a coûté, puis la correction, sous la forme du réglage exact à changer. Un outil qui n&#39;a rien coûté est listé aussi, en vert, pour voir à quoi ressemble le bon comportement.</p><p>Ce qu&#39;un outil se coûte à lui-même est affiché mais jamais compté contre lui.</p><h2 id="comment-les-couts-sont-attribues" tabindex="-1">Comment les coûts sont attribués <a class="header-anchor" href="#comment-les-couts-sont-attribues" aria-label="Permalink to &quot;Comment les coûts sont attribués&quot;">​</a></h2><p>Les règles sont assez simples pour être énoncées, et la page les énonce :</p><ul><li>Un (re)chargement de modèle est imputé à qui a déchargé le modèle. Si la requête précédente au même modèle demandait <code>keep_alive: 0</code>, c&#39;est cet outil qui l&#39;a causé. Si un autre modèle a été utilisé entre-temps, c&#39;est l&#39;outil qui a chargé cet autre modèle. Sinon, le modèle est resté inactif plus longtemps que <code>keep_alive</code>, et le rechargement n&#39;est la faute de personne.</li><li>Une attente est imputée à la requête que le démon servait encore quand celle-ci est arrivée.</li></ul><h2 id="combien-d-outils-a-la-fois" tabindex="-1">Combien d&#39;outils à la fois <a class="header-anchor" href="#combien-d-outils-a-la-fois" aria-label="Permalink to &quot;Combien d&#39;outils à la fois&quot;">​</a></h2><p>Ollama sert plusieurs requêtes en même temps seulement tant qu&#39;elles tiennent en mémoire vidéo. Quand un outil réserve un grand contexte, le démon passe sans rien dire à moins de requêtes à la fois. Il ne le dit nulle part ; la page le lit dans le contexte chargé que le démon annonce, comparé au contexte que chaque requête a demandé, et indique le moment où le nombre a baissé et la requête de quel outil l&#39;a provoqué.</p><h2 id="ce-qui-s-est-passe-dans-l-ordre" tabindex="-1">Ce qui s&#39;est passé, dans l&#39;ordre <a class="header-anchor" href="#ce-qui-s-est-passe-dans-l-ordre" aria-label="Permalink to &quot;Ce qui s&#39;est passé, dans l&#39;ordre&quot;">​</a></h2><p>Chaque chargement et chaque attente, avec l&#39;heure, l&#39;outil qui a payé, et qui l&#39;a causé quand c&#39;était un autre outil.</p><h2 id="ce-que-la-page-ne-sait-pas" tabindex="-1">Ce que la page ne sait pas <a class="header-anchor" href="#ce-que-la-page-ne-sait-pas" aria-label="Permalink to &quot;Ce que la page ne sait pas&quot;">​</a></h2><p>Tout ce qui n&#39;est pas passé par le port d&#39;observation. Un outil qui parle directement à Ollama sur 11434 est invisible ici, ce qui vaut la peine d&#39;être su quand les chiffres ne tombent pas juste. L&#39;attente en file est notre temps total moins celui du démon, c&#39;est donc une estimation.</p><h2 id="voir-aussi" tabindex="-1">Voir aussi <a class="header-anchor" href="#voir-aussi" aria-label="Permalink to &quot;Voir aussi&quot;">​</a></h2><ul><li><a href="./live.html">En direct</a> enregistre les tours.</li><li><a href="./gpu-map.html">Carte du GPU</a> montre ce que les contextes réservés occupent en mémoire vidéo.</li></ul>',23)])])}const h=a(o,[["render",l]]);export{m as __pageData,h as default};
